//! The paths a server runs over and over, measured end to end.
//!
//! The plugin is loaded the way a server loads it — `Supports`, `Load` and
//! `AmxLoad` generated by `initialize_plugin!` — against an AMX built here: a
//! header, a data segment and an export table whose functions follow
//! `amx.c`. So a native call below goes through the same generated wrapper,
//! argument parsing and plugin lookup as on a server, and a `public` through
//! the same `amx_Exec` detour.
//!
//! What it cannot show is the server's own cost (its `amx_Exec`, its natives);
//! the fake export functions are as cheap as the real ones or cheaper, so the
//! numbers are the SDK's share.
//!
//! Run with:
//!
//! ```sh
//! cargo bench -p rust-samp --bench hot_paths --target i686-unknown-linux-gnu
//! ```

use std::ffi::{CStr, c_char};
use std::hint::black_box;

use criterion::{Criterion, criterion_group, criterion_main};
use samp::prelude::*;
use samp::raw::types::{AMX, AMX_HEADER, AMX_NATIVE_INFO};
use samp::{event, initialize_plugin, native};

// ---------------------------------------------------------------------------
// The plugin under test
// ---------------------------------------------------------------------------

struct Bench {
    hits: u32,
}

impl SampPlugin for Bench {}

impl Bench {
    #[native(name = "Bench_Int")]
    fn int(&mut self, _amx: &Amx, a: i32, b: i32) -> i32 {
        a.wrapping_add(b)
    }

    #[native(name = "Bench_Ref")]
    fn by_ref(&mut self, _amx: &Amx, mut out: Ref<i32>) -> bool {
        *out += 1;
        true
    }

    #[native(name = "Bench_String")]
    fn string(&mut self, _amx: &Amx, name: &AmxString) -> i32 {
        i32::try_from(name.len()).unwrap_or(0)
    }

    #[native(name = "Bench_Decode")]
    fn decode(&mut self, _amx: &Amx, name: &AmxString) -> i32 {
        i32::from(name.starts_with('A'))
    }

    #[native(name = "Bench_Write")]
    fn write(&mut self, _amx: &Amx, dest: UnsizedBuffer, size: usize) -> AmxResult<bool> {
        dest.write_str(size, "Hello, world")?;
        Ok(true)
    }

    #[event(name = "OnHooked")]
    fn on_hooked(&mut self, _amx: &Amx, playerid: i32) -> EventReturn {
        self.hits = self.hits.wrapping_add(playerid.cast_unsigned());
        EventReturn::Continue
    }

    #[event(name = "OnCancelled")]
    fn on_cancelled(&mut self, _amx: &Amx, _playerid: i32) -> EventReturn {
        EventReturn::Suppress(0)
    }
}

initialize_plugin!(
    natives: [Bench::int, Bench::by_ref, Bench::string, Bench::decode, Bench::write],
    events: [Bench::on_hooked, Bench::on_cancelled],
    {
        return Bench { hits: 0 };
    }
);

// ---------------------------------------------------------------------------
// A VM: header, data segment, export table
// ---------------------------------------------------------------------------

const HEADER: usize = 64;
const DATA_CELLS: usize = 16 * 1024;
const HEAP_TOP: i32 = 8 * 1024 * 4;
const STACK_TOP: i32 = (DATA_CELLS * 4) as i32;

/// Publics of the fake script: `OnHooked` has an `#[event]` handler that lets
/// it run, `OnPlain` has none, `OnCancelled` one that suppresses it.
const PUBLICS: [&CStr; 3] = [c"OnHooked", c"OnPlain", c"OnCancelled"];

fn data(amx: *mut AMX) -> *mut u8 {
    unsafe { (*amx).base.add(HEADER) }
}

extern "C" fn get_addr(amx: *mut AMX, addr: i32, phys: *mut *mut i32) -> i32 {
    let amx_ref = unsafe { &*amx };
    if (addr >= amx_ref.hea && addr < amx_ref.stk) || addr < 0 || addr >= amx_ref.stp {
        return 5; // AMX_ERR_MEMACCESS
    }
    unsafe { *phys = data(amx).add(addr as usize).cast() };
    0
}

extern "C" fn str_len(cstr: *const i32, len: *mut i32) -> i32 {
    let mut n = 0;
    unsafe {
        while *cstr.add(n) != 0 {
            n += 1;
        }
        *len = n as i32;
    }
    0
}

extern "C" fn register(_amx: *mut AMX, _natives: *const AMX_NATIVE_INFO, _count: i32) -> i32 {
    0
}

extern "C" fn find_public(_amx: *mut AMX, name: *const c_char, index: *mut i32) -> i32 {
    let name = unsafe { CStr::from_ptr(name) };
    match PUBLICS.iter().position(|p| *p == name) {
        Some(i) => {
            unsafe { *index = i as i32 };
            0
        }
        None => 19, // AMX_ERR_NOTFOUND
    }
}

/// `amx_Exec`, as far as a caller can tell: consumes the pushed arguments.
///
/// Touches no `static`: in i686 position-independent code that would start
/// the function with a `get_pc_thunk` call, which the detour's relocated
/// prologue cannot carry. The servers' `amx_Exec` does not start that way.
#[inline(never)]
extern "C" fn exec(amx: *mut AMX, retval: *mut i32, _index: i32) -> i32 {
    unsafe {
        if !retval.is_null() {
            *retval = 1;
        }
        (*amx).stk += (*amx).paramcount * 4;
        (*amx).paramcount = 0;
    }
    0
}

extern "C" fn allot(amx: *mut AMX, cells: i32, amx_addr: *mut i32, phys: *mut *mut i32) -> i32 {
    let amx_ref = unsafe { &mut *amx };
    let Some(top) = amx_ref.hea.checked_add(cells * 4) else {
        return 1;
    };
    if top >= amx_ref.stk {
        return 1; // AMX_ERR_MEMORY
    }
    unsafe {
        *amx_addr = amx_ref.hea;
        *phys = data(amx).add(amx_ref.hea as usize).cast();
    }
    amx_ref.hea = top;
    0
}

extern "C" fn release(amx: *mut AMX, amx_addr: i32) -> i32 {
    let amx_ref = unsafe { &mut *amx };
    if amx_ref.hea > amx_addr {
        amx_ref.hea = amx_addr;
    }
    0
}

extern "C" fn push(amx: *mut AMX, value: i32) -> i32 {
    let amx_ref = unsafe { &mut *amx };
    amx_ref.stk -= 4;
    unsafe { *data(amx).add(amx_ref.stk as usize).cast::<i32>() = value };
    amx_ref.paramcount += 1;
    0
}

extern "C" fn logprintf(_line: *const c_char) {}

extern "C" fn callback(_amx: *mut AMX, _index: i32, _result: *mut i32, _params: *mut i32) -> i32 {
    0
}

extern "C" fn debug(_amx: *mut AMX) -> i32 {
    0
}

fn exports() -> Vec<usize> {
    let mut table = vec![0usize; 64];
    table[13] = get_addr as *const () as usize;
    table[39] = str_len as *const () as usize;
    table[33] = register as *const () as usize;
    table[9] = find_public as *const () as usize;
    table[7] = exec as *const () as usize;
    table[3] = allot as *const () as usize;
    table[34] = release as *const () as usize;
    table[29] = push as *const () as usize;
    table
}

struct Vm {
    amx: Box<AMX>,
    _memory: Vec<u32>,
}

impl Vm {
    fn new() -> Self {
        let mut memory = vec![0u32; (HEADER + DATA_CELLS * 4) / 4];
        let base = memory.as_mut_ptr().cast::<u8>();
        let header = base.cast::<AMX_HEADER>();
        unsafe { (*header).dat = HEADER as i32 };
        let amx = Box::new(AMX {
            base,
            data: std::ptr::null_mut(),
            callback,
            debug,
            cip: 0,
            frm: 0,
            hea: HEAP_TOP,
            hlw: HEAP_TOP,
            stk: STACK_TOP,
            stp: STACK_TOP,
            flags: 0,
            usertags: [0; 4],
            userdata: [std::ptr::null_mut(); 4],
            error: 0,
            paramcount: 0,
            pri: 0,
            alt: 0,
            reset_stk: 0,
            reset_hea: 0,
            sysreq_d: 0,
        });
        Vm {
            amx,
            _memory: memory,
        }
    }

    fn ptr(&mut self) -> *mut AMX {
        &raw mut *self.amx
    }

    /// Writes `text` unpacked at `addr`, terminated.
    fn put_string(&mut self, addr: i32, text: &str) {
        let cells = unsafe { data(self.ptr()).add(addr as usize).cast::<i32>() };
        for (i, b) in text.bytes().enumerate() {
            unsafe { *cells.add(i) = i32::from(b) };
        }
        unsafe { *cells.add(text.len()) = 0 };
    }

    /// Pushes `args` the way the VM does before `amx_Exec`.
    fn push(&mut self, args: &[i32]) {
        for &arg in args.iter().rev() {
            self.amx.stk -= 4;
            let at = self.amx.stk;
            unsafe { *data(self.ptr()).add(at as usize).cast::<i32>() = arg };
        }
        self.amx.paramcount = args.len() as i32;
    }
}

type NativeFn = extern "C" fn(*mut AMX, *mut i32) -> i32;

/// Calls a native the way the VM does: `params[0]` is the argument bytes.
/// The parameter block lives on the stack, as the VM's does.
fn call(native: NativeFn, amx: *mut AMX, args: &[i32]) -> i32 {
    let mut params = [0i32; 8];
    params[0] = (args.len() * 4) as i32;
    params[1..=args.len()].copy_from_slice(args);
    native(amx, params.as_mut_ptr())
}

// ---------------------------------------------------------------------------
// Benchmarks
// ---------------------------------------------------------------------------

struct Loaded {
    vm: Vm,
    table: Vec<usize>,
    _server: Vec<usize>,
}

/// Loads the plugin once, as a server does, and keeps the VM for every group.
fn setup() -> &'static mut Loaded {
    static LOADED: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    let ptr = *LOADED.get_or_init(|| {
        let table = exports();
        let mut server = vec![0usize; 32];
        server[0] = logprintf as *const () as usize;
        server[16] = table.as_ptr() as usize;
        let mut vm = Vm::new();
        let _ = Supports();
        Load(server.as_ptr());
        AmxLoad(vm.ptr());
        Box::into_raw(Box::new(Loaded {
            vm,
            table,
            _server: server,
        })) as usize
    });
    // Benchmarks run one at a time on this thread.
    unsafe { &mut *(ptr as *mut Loaded) }
}

fn natives(c: &mut Criterion) {
    let vm = &mut setup().vm;
    let amx = vm.ptr();
    const NAME: i32 = 1024;
    const OUT: i32 = 4096;
    const DEST: i32 = 8192;
    vm.put_string(NAME, "Alexander");
    let long: String = "A".repeat(127);
    vm.put_string(2048, &long);

    let mut group = c.benchmark_group("native");
    group.bench_function("two_ints", |b| {
        b.iter(|| call(Bench::__samp_native_int, amx, black_box(&[1, 2])))
    });
    group.bench_function("ref", |b| {
        b.iter(|| call(Bench::__samp_native_by_ref, amx, black_box(&[OUT])))
    });
    group.bench_function("string_len_9", |b| {
        b.iter(|| call(Bench::__samp_native_string, amx, black_box(&[NAME])))
    });
    group.bench_function("string_len_127", |b| {
        b.iter(|| call(Bench::__samp_native_string, amx, black_box(&[2048])))
    });
    group.bench_function("string_decoded_9", |b| {
        b.iter(|| call(Bench::__samp_native_decode, amx, black_box(&[NAME])))
    });
    group.bench_function("string_decoded_127", |b| {
        b.iter(|| call(Bench::__samp_native_decode, amx, black_box(&[2048])))
    });
    group.bench_function("write_str", |b| {
        b.iter(|| call(Bench::__samp_native_write, amx, black_box(&[DEST, 64])))
    });
    group.finish();
}

fn publics(c: &mut Criterion) {
    let loaded = setup();
    let table = loaded.table.clone();
    let vm = &mut loaded.vm;
    let amx = vm.ptr();
    // The detour is installed on `exec`; calling it now goes through it.
    let exec_fn: extern "C" fn(*mut AMX, *mut i32, i32) -> i32 =
        unsafe { std::mem::transmute(table[7]) };

    let mut group = c.benchmark_group("public");
    group.bench_function("with_event_handler", |b| {
        b.iter(|| {
            vm.push(&[7]);
            let mut ret = 0;
            exec_fn(amx, &raw mut ret, black_box(0));
            ret
        })
    });
    group.bench_function("without_handler", |b| {
        b.iter(|| {
            vm.push(&[7]);
            let mut ret = 0;
            exec_fn(amx, &raw mut ret, black_box(1));
            ret
        })
    });
    group.bench_function("suppressed", |b| {
        b.iter(|| {
            vm.push(&[7]);
            let mut ret = 0;
            exec_fn(amx, &raw mut ret, black_box(2));
            ret
        })
    });
    group.finish();
    // Every call above consumed what it pushed, suppressed ones included.
    assert_eq!(
        { vm.amx.stk },
        STACK_TOP,
        "a public left its arguments on the stack"
    );
}

/// Calling a script's public from Rust, the way a plugin answers a script.
fn calls(c: &mut Criterion) {
    let loaded = setup();
    let amx = samp::amx::get(samp::amx::AmxIdent::from(loaded.vm.ptr())).unwrap();
    let mut group = c.benchmark_group("call_public");
    group.bench_function("no_args", |b| {
        b.iter(|| samp::exec_public!(amx, black_box("OnPlain")))
    });
    group.bench_function("int_float", |b| {
        b.iter(|| amx.call_public(black_box("OnPlain"), (7, 1.5_f32)))
    });
    group.bench_function("int_string", |b| {
        b.iter(|| amx.call_public(black_box("OnPlain"), (7, black_box("headshot"))))
    });
    group.finish();
}

fn runtime(c: &mut Criterion) {
    setup();
    let mut group = c.benchmark_group("runtime");
    group.bench_function("tick_idle", |b| {
        b.iter(|| samp::interlayer::tick(samp::plugin::TickSource::SaMp))
    });
    group.bench_function("post_and_drain", |b| {
        b.iter(|| {
            samp::mainthread::post(|| {
                black_box(1);
            });
            samp::mainthread::run_pending()
        })
    });
    group.finish();
}

fn logging(c: &mut Criterion) {
    setup();
    let dir = std::env::temp_dir().join("rust-samp-bench-logs");
    let _ = samp::enable_logger_with!(
        samp::logger::LoggerConfig::new("bench")
            .directory(&dir)
            .no_banner()
            .no_rotation()
    );
    // A server always has more threads than this one, and the local time is
    // slower to read then.
    let (stop, alive) = std::sync::mpsc::channel::<()>();
    let other = std::thread::spawn(move || {
        let _ = alive.recv();
    });
    let mut group = c.benchmark_group("log");
    group.bench_function("info_line", |b| {
        b.iter(|| samp::log::info!("player {} said {}", black_box(7), black_box("hello")))
    });
    samp::logger::set_level(samp::log::LevelFilter::Warn);
    group.bench_function("filtered_out", |b| {
        b.iter(|| samp::log::info!("player {} said {}", black_box(7), black_box("hello")))
    });
    group.finish();
    drop(stop);
    let _ = other.join();
    let _ = std::fs::remove_dir_all(dir);
}

criterion_group!(benches, natives, publics, calls, runtime, logging);
criterion_main!(benches);
